import sys
sys.setrecursionlimit(500000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        N = int(next(iterator))
        K = int(next(iterator))
        a = int(next(iterator))

        f = []
        for _ in range(K):
            f.append(int(next(iterator)))

        adj = [[] for _ in range(N + 1)]
        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        def bfs(start_node):
            dist = [-1] * (N + 1)
            parent = [0] * (N + 1)
            dist[start_node] = 0
            queue = [start_node]

            head = 0
            while head < len(queue):
                u = queue[head]
                head += 1
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
            return dist, parent, queue

        dist_a, _, order_a = bfs(a)

        best_val = [-float('inf')] * (N + 1)
        best_node = [0] * (N + 1)

        for u in f:
            val = dist_a[u]
            if val > best_val[a]:
                best_val[a] = val
                best_node[a] = u
            elif val == best_val[a]:
                if best_node[a] == 0 or u < best_node[a]:
                    best_node[a] = u

        dist_f = {}
        for u in f:
            dist_f[u] = 0

        for u in f:
            d_u, _, _ = bfs(u)
            for node in range(1, N + 1):
                val = dist_a[u] - d_u[node]
                if val > best_val[node]:
                    best_val[node] = val
                    best_node[node] = u
                elif val == best_val[node]:
                    if best_node[node] == 0 or u < best_node[node]:
                        best_node[node] = u

        res_vals = []
        res_nodes = []
        for i in range(1, N + 1):
            res_vals.append(str(best_val[i]))
            res_nodes.append(str(best_node[i]))

        out_lines.append(" ".join(res_vals))
        out_lines.append(" ".join(res_nodes))

    sys.stdout.write("\n".join(out_lines) + "\n")

if __name__ == "__main__":
    solve()
